insert into settings (id, store_name, tagline, tagline_en, whatsapp_number, bank_name, bank_account, bank_holder, qris_image_url, cutoff_time, min_order_retail, min_order_business, free_delivery_retail, free_delivery_business, catch_weight_buffer_pct, max_days_ahead, instagram, address_line, announcement, announcement_en, hero_image_url, about_image_url) values (1, 'Dipasaria', 'Protein pilihan untuk dapur Jakarta', 'Trusted protein for Jakarta''s kitchens', '6281100000000', 'BCA', '0000000000', 'PT Dipasaria', null, '20:00', 150000, 750000, 250000, 750000, 5, 6, 'dipasaria.id', 'Jakarta Utara', null, null, null, null)
insert into categories (id, slug, name, name_en, description, description_en, sort, icon, image_url, is_seafood) values
  ('c_ikan', 'ikan-segar', 'Ikan Segar', 'Fresh Fish', 'Dilelang di Muara Baru sebelum subuh, dinamai spesiesnya, digrade ukurannya.', 'Auctioned at Muara Baru before dawn, named by species, graded by size.', 1, 'fish', '/images/site/cat-ikan-segar.jpg', true),
  ('c_udang', 'udang-cumi', 'Udang & Cumi', 'Shrimp & Squid', 'Udang vaname berukuran dan cumi segar, siap dikupas atau dibersihkan.', 'Sized vannamei shrimp and fresh squid, ready to peel or clean.', 2, 'shrimp', '/images/site/cat-udang-cumi.jpg', true),
  ('c_beku', 'seafood-beku', 'Seafood Beku', 'Frozen Seafood', 'Fillet dan portion beku untuk stok freezer, tanpa risiko basi.', 'Fillets and portions for the freezer, no spoilage risk.', 3, 'snow', '/images/site/cat-seafood-beku.jpg', true),
  ('c_ayam', 'ayam', 'Ayam', 'Chicken', 'Ayam potong dari RPHU bersertifikat halal, beku atau segar untuk akun bisnis.', 'Cut chicken from halal-certified slaughterhouses, frozen or fresh for business accounts.', 4, 'chicken', '/images/site/cat-ayam.jpg', false),
  ('c_olahan', 'frozen-food', 'Frozen Food', 'Frozen Food', 'Nugget, sosis dan bakso ikan dari merek ber-BPOM dan berlogo halal.', 'Nuggets, sausages and fish balls from BPOM-registered, halal-labelled brands.', 5, 'box', '/images/site/cat-frozen-food.jpg', false),
  ('c_telur', 'telur', 'Telur', 'Eggs', 'Telur ayam segar per tray, atau per peti untuk restoran.', 'Fresh chicken eggs by the tray, or by the crate for restaurants.', 6, 'egg', '/images/site/cat-telur.jpg', false),
  ('c_paket', 'paket-hemat', 'Paket Hemat', 'Value Boxes', 'Kotak siap isi freezer dengan harga di bawah membeli satuan.', 'Freezer-ready boxes priced below buying the items separately.', 8, 'box', '/images/products/kotak-freezer-keluarga.jpg', false),
  ('c_bumbu', 'bumbu-dapur', 'Bumbu & Dapur', 'Pantry & Condiments', 'Kebutuhan dapur yang Anda beli setiap minggu, ikut dalam pengiriman yang sama.', 'The kitchen staples you buy every week, in the same delivery.', 7, 'bottle', '/images/site/cat-bumbu-dapur.jpg', false)
insert into products (id, slug, category_id, name, name_en, scientific_name, aliases, description, description_en, origin, origin_en, storage_class, storage_note, storage_note_en, is_catch_weight, available_today, is_active, is_featured, image_url, icon, sort) values
  ('p_kakap', 'kakap-merah', 'c_ikan', 'Kakap Merah', 'Malabar Snapper', 'Lutjanus malabaricus', array['bambangan','red snapper','kakap']::text[], 'Kakap merah yang benar, bukan Red Bass yang sering dijual sebagai kakap. Daging putih padat untuk kukus, bakar atau goreng.', 'The true red snapper, not the Red Bass often sold under that name. Firm white flesh for steaming, grilling or frying.', 'Muara Baru, didaratkan subuh', 'Muara Baru, landed at dawn', 'chilled', 'Simpan 0–4 °C, masak dalam 24 jam atau bekukan.', 'Keep at 0–4 °C; cook within 24 hours or freeze.', true, true, true, true, '/images/products/kakap-merah.jpg', 'fish', 1),
  ('p_kerapu', 'kerapu', 'c_ikan', 'Kerapu', 'Orange-spotted Grouper', 'Epinephelus coioides', array['grouper','kerapu lumpur','kerapu macan']::text[], 'Kerapu budidaya dengan pasokan stabil. Pilihan utama untuk hidangan ikan kukus restoran.', 'Farmed grouper with a steady supply. The restaurant choice for steamed whole fish.', 'Tambak Lampung & Kepulauan Seribu via Muara Baru', 'Lampung and Seribu Islands farms via Muara Baru', 'chilled', 'Simpan 0–4 °C, masak dalam 24 jam atau bekukan.', 'Keep at 0–4 °C; cook within 24 hours or freeze.', true, true, true, true, '/images/products/kerapu.jpg', 'fish', 2),
  ('p_kembung', 'kembung', 'c_ikan', 'Kembung', 'Indian Mackerel', 'Rastrelliger kanagurta', array['mackerel','kembung banjar']::text[], 'Ikan rakyat dengan omega-3 tinggi. Volume harian untuk dapur Padang dan warung.', 'The everyday fish, high in omega-3. Daily volume for Padang kitchens and warungs.', 'Muara Baru, didaratkan subuh', 'Muara Baru, landed at dawn', 'chilled', 'Simpan 0–4 °C, masak dalam 24 jam atau bekukan.', 'Keep at 0–4 °C; cook within 24 hours or freeze.', true, true, true, false, '/images/products/kembung.jpg', 'fish', 3),
  ('p_tongkol', 'tongkol', 'c_ikan', 'Tongkol', 'Mackerel Tuna', 'Euthynnus affinis', array['tuna','tongkol abu']::text[], 'Tongkol segar untuk balado, pindang dan suwir.', 'Fresh mackerel tuna for balado, pindang and shredded dishes.', 'Muara Baru, didaratkan subuh', 'Muara Baru, landed at dawn', 'chilled', 'Simpan 0–4 °C, masak dalam 24 jam atau bekukan.', 'Keep at 0–4 °C; cook within 24 hours or freeze.', true, true, true, false, '/images/products/tongkol.jpg', 'fish', 4),
  ('p_bandeng', 'bandeng', 'c_ikan', 'Bandeng', 'Milkfish', 'Chanos chanos', array['milkfish','bandeng presto']::text[], 'Bandeng tambak Lampung dengan opsi cabut duri untuk keluarga.', 'Lampung pond milkfish, with a deboning option for families.', 'Tambak Lampung via Muara Baru', 'Lampung ponds via Muara Baru', 'chilled', 'Simpan 0–4 °C, masak dalam 24 jam atau bekukan.', 'Keep at 0–4 °C; cook within 24 hours or freeze.', true, true, true, false, '/images/products/bandeng.jpg', 'fish', 5),
  ('p_baronang', 'baronang', 'c_ikan', 'Baronang', 'Rabbitfish', 'Siganus spp.', array['rabbitfish','beronang']::text[], 'Ikan bakar favorit restoran seafood, daging manis dan tidak amis.', 'The seafood restaurant grilling favourite: sweet flesh, never fishy.', 'Muara Baru, didaratkan subuh', 'Muara Baru, landed at dawn', 'chilled', 'Simpan 0–4 °C, masak dalam 24 jam atau bekukan.', 'Keep at 0–4 °C; cook within 24 hours or freeze.', true, false, true, false, '/images/products/baronang.jpg', 'fish', 6),
  ('p_bawal', 'bawal-putih', 'c_ikan', 'Bawal Putih', 'Silver Pomfret', 'Pampus argenteus', array['pomfret','bawal']::text[], 'Bawal putih premium untuk kukus ala Chinese-Indonesian.', 'Premium silver pomfret for Chinese-Indonesian steamed dishes.', 'Muara Baru, didaratkan subuh', 'Muara Baru, landed at dawn', 'chilled', 'Simpan 0–4 °C, masak dalam 24 jam atau bekukan.', 'Keep at 0–4 °C; cook within 24 hours or freeze.', true, true, true, false, '/images/products/bawal-putih.jpg', 'fish', 7),
  ('p_nila', 'nila-merah', 'c_ikan', 'Nila Merah', 'Red Tilapia', 'Oreochromis sp.', array['tilapia','nila']::text[], 'Nila budidaya Jawa Barat, ukuran konsisten, ramah anak jika difillet.', 'West Java farmed tilapia, consistent sizing, child-friendly when filleted.', 'Kolam Sukabumi & Indramayu', 'Sukabumi and Indramayu ponds', 'chilled', 'Simpan 0–4 °C, masak dalam 24 jam atau bekukan.', 'Keep at 0–4 °C; cook within 24 hours or freeze.', true, true, true, false, '/images/products/nila-merah.jpg', 'fish', 8),
  ('p_udang', 'udang-vaname', 'c_udang', 'Udang Vaname Segar', 'Whiteleg Shrimp', 'Litopenaeus vannamei', array['shrimp','prawn','udang putih','vannamei']::text[], 'Udang vaname tambak, dihitung per kg (size = jumlah ekor per kg). Tanpa perendaman penambah berat.', 'Pond-raised vannamei, sold per kg (size = pieces per kg). No weight-adding soak.', 'Tambak Lampung & Indramayu', 'Lampung and Indramayu ponds', 'chilled', 'Simpan 0–4 °C, masak dalam 24 jam atau bekukan.', 'Keep at 0–4 °C; cook within 24 hours or freeze.', true, true, true, true, '/images/products/udang-vaname.jpg', 'shrimp', 9),
  ('p_cumi', 'cumi-segar', 'c_udang', 'Cumi Segar', 'Squid', 'Loligo spp.', array['squid','sotong','cumi-cumi']::text[], 'Cumi segar hasil lelang subuh, bisa dibersihkan dan dipotong ring.', 'Fresh squid from the dawn auction; can be cleaned and cut into rings.', 'Muara Baru, didaratkan subuh', 'Muara Baru, landed at dawn', 'chilled', 'Simpan 0–4 °C, masak dalam 24 jam atau bekukan.', 'Keep at 0–4 °C; cook within 24 hours or freeze.', true, true, true, true, null, 'squid', 10),
  ('p_udang_beku', 'udang-kupas-beku', 'c_beku', 'Udang Vaname Kupas PD Beku', 'Peeled & Deveined Shrimp', 'Litopenaeus vannamei', array['udang beku','frozen shrimp','pd shrimp']::text[], 'Udang kupas belah punggung, IQF, siap tumis. Andalan stok freezer rumah tangga.', 'Peeled, deveined, IQF shrimp ready to stir-fry. The household freezer staple.', 'Cold storage Lampung', 'Lampung cold storage', 'frozen', 'Simpan −18 °C. Cairkan di kulkas bawah, jangan di suhu ruang.', 'Keep at −18 °C. Thaw in the fridge, never at room temperature.', false, true, true, true, '/images/products/udang-kupas-beku.jpg', 'shrimp', 11),
  ('p_dori', 'dori-fillet', 'c_beku', 'Dori Fillet Beku', 'Pangasius Fillet', 'Pangasius hypophthalmus', array['dory','patin fillet','ikan dori']::text[], 'Fillet dori tanpa duri untuk fish & chips, kafe dan menu anak.', 'Boneless pangasius fillet for fish and chips, cafés and children''s menus.', 'Pengolah Lampung (SKP/HACCP)', 'Lampung processor (SKP/HACCP)', 'frozen', 'Simpan −18 °C. Cairkan di kulkas bawah, jangan di suhu ruang.', 'Keep at −18 °C. Thaw in the fridge, never at room temperature.', false, true, true, false, '/images/products/dori-fillet.jpg', 'fillet', 12),
  ('p_tuna', 'tuna-saku', 'c_beku', 'Tuna Saku Beku', 'Yellowfin Tuna Saku', 'Thunnus albacares', array['tuna','saku','tuna loin']::text[], 'Tuna saku grade sashimi-ready setelah dicairkan dengan benar.', 'Tuna saku, sashimi-ready when thawed correctly.', 'Bitung, via distributor Jakarta', 'Bitung, via Jakarta distributor', 'frozen', 'Simpan −18 °C. Cairkan di kulkas bawah, jangan di suhu ruang.', 'Keep at −18 °C. Thaw in the fridge, never at room temperature.', false, true, true, false, '/images/products/tuna-saku.jpg', 'fillet', 13),
  ('p_salmon', 'salmon-fillet', 'c_beku', 'Salmon Fillet Beku', 'Atlantic Salmon Portion', 'Salmo salar', array['salmon','salmon norway']::text[], 'Portion salmon impor dari importir berizin, dipotong 200 g siap panggang.', 'Imported salmon portions from a licensed importer, cut to 200 g ready to grill.', 'Norwegia, importir berizin Jakarta', 'Norway, licensed Jakarta importer', 'frozen', 'Simpan −18 °C. Cairkan di kulkas bawah, jangan di suhu ruang.', 'Keep at −18 °C. Thaw in the fridge, never at room temperature.', false, true, true, true, '/images/products/salmon-fillet.jpg', 'fillet', 14),
  ('p_tenggiri', 'tenggiri-steak', 'c_beku', 'Tenggiri Steak Beku', 'Spanish Mackerel Steak', 'Scomberomorus commerson', array['tenggiri','mackerel steak']::text[], 'Steak tenggiri untuk bakar dan goreng, atau bahan pempek dan otak-otak.', 'Spanish mackerel steaks for grilling and frying, or for pempek and otak-otak.', 'Muara Baru, dibekukan dalam 4 jam', 'Muara Baru, frozen within 4 hours', 'frozen', 'Simpan −18 °C. Cairkan di kulkas bawah, jangan di suhu ruang.', 'Keep at −18 °C. Thaw in the fridge, never at room temperature.', false, true, true, false, '/images/products/tenggiri-steak.jpg', 'fillet', 15),
  ('p_sayap', 'sayap-ayam-beku', 'c_ayam', 'Sayap Ayam Beku', 'Chicken Wings', null, array['wings','chicken wing']::text[], 'Sayap ayam dari RPHU bersertifikat halal dan NKV, dibekukan segar.', 'Chicken wings from a halal-certified, NKV-registered slaughterhouse, frozen fresh.', 'RPHU bersertifikat halal, Jawa Barat', 'Halal-certified slaughterhouse, West Java', 'frozen', 'Simpan −18 °C. Cairkan di kulkas bawah, jangan di suhu ruang.', 'Keep at −18 °C. Thaw in the fridge, never at room temperature.', false, true, true, false, '/images/products/sayap-ayam-beku.jpg', 'chicken', 16),
  ('p_paha', 'paha-ayam-beku', 'c_ayam', 'Paha Ayam Beku', 'Chicken Thigh', null, array['thigh','paha bawah','paha atas']::text[], 'Paha ayam utuh, ukuran seragam 180–220 g per potong.', 'Whole chicken thighs, uniform 180–220 g pieces.', 'RPHU bersertifikat halal, Jawa Barat', 'Halal-certified slaughterhouse, West Java', 'frozen', 'Simpan −18 °C. Cairkan di kulkas bawah, jangan di suhu ruang.', 'Keep at −18 °C. Thaw in the fridge, never at room temperature.', false, true, true, false, '/images/products/paha-ayam-beku.jpg', 'chicken', 17),
  ('p_dada', 'dada-fillet-ayam', 'c_ayam', 'Dada Fillet Ayam Beku', 'Boneless Chicken Breast', null, array['fillet ayam','chicken breast','dada ayam']::text[], 'Dada tanpa tulang dan kulit, untuk geprek, katsu dan menu sehat.', 'Boneless, skinless breast for geprek, katsu and healthy menus.', 'RPHU bersertifikat halal, Jawa Barat', 'Halal-certified slaughterhouse, West Java', 'frozen', 'Simpan −18 °C. Cairkan di kulkas bawah, jangan di suhu ruang.', 'Keep at −18 °C. Thaw in the fridge, never at room temperature.', false, true, true, true, '/images/products/dada-fillet-ayam.jpg', 'chicken', 18),
  ('p_ayam_segar', 'ayam-potong-segar', 'c_ayam', 'Ayam Potong Segar', 'Fresh Chicken, cut', null, array['ayam segar','ayam potong 8','broiler']::text[], 'Ayam broiler segar dipotong 8 atau 12, dari RPHU bersertifikat halal. Khusus akun restoran, harga mengikuti indeks pasar mingguan.', 'Fresh broiler cut into 8 or 12 from a halal-certified slaughterhouse. Business accounts only; priced to the weekly market index.', 'RPHU bersertifikat halal, Bogor', 'Halal-certified slaughterhouse, Bogor', 'chilled', 'Simpan 0–4 °C, dikemas terpisah dari ikan.', null, true, true, true, false, '/images/products/ayam-potong-segar.jpg', 'chicken', 19),
  ('p_nugget', 'nugget-ayam', 'c_olahan', 'Nugget Ayam', 'Chicken Nuggets', null, array['nugget','naget']::text[], 'Nugget ayam merek nasional ber-BPOM MD dan berlogo halal.', 'National-brand chicken nuggets, BPOM-registered with a halal logo.', 'Distributor resmi', 'Authorised distributor', 'frozen', 'Simpan −18 °C. Cairkan di kulkas bawah, jangan di suhu ruang.', 'Keep at −18 °C. Thaw in the fridge, never at room temperature.', false, true, true, true, '/images/products/nugget-ayam.jpg', 'box', 20),
  ('p_sosis', 'sosis-ayam', 'c_olahan', 'Sosis Ayam', 'Chicken Sausage', null, array['sosis','sausage']::text[], 'Sosis ayam premium untuk sarapan, bento dan menu kafe.', 'Premium chicken sausages for breakfast, bento and café menus.', 'Distributor resmi', 'Authorised distributor', 'frozen', 'Simpan −18 °C. Cairkan di kulkas bawah, jangan di suhu ruang.', 'Keep at −18 °C. Thaw in the fridge, never at room temperature.', false, true, true, false, '/images/products/sosis-ayam.jpg', 'box', 21),
  ('p_bakso', 'bakso-ikan', 'c_olahan', 'Bakso Ikan', 'Fish Balls', null, array['fish ball','baso ikan']::text[], 'Bakso ikan kenyal untuk sup, tomyam dan steamboat.', 'Springy fish balls for soups, tom yum and steamboat.', 'Distributor resmi', 'Authorised distributor', 'frozen', 'Simpan −18 °C. Cairkan di kulkas bawah, jangan di suhu ruang.', 'Keep at −18 °C. Thaw in the fridge, never at room temperature.', false, true, true, false, '/images/products/bakso-ikan.jpg', 'box', 22),
  ('p_otak', 'otak-otak', 'c_olahan', 'Otak-otak Tenggiri', 'Grilled Fish Cake', null, array['otak otak','otak-otak bakar']::text[], 'Otak-otak tenggiri beku, tinggal bakar atau kukus 10 menit.', 'Frozen Spanish-mackerel otak-otak; grill or steam for 10 minutes.', 'Produsen UMKM bersertifikat PIRT', 'PIRT-certified small producer', 'frozen', 'Simpan −18 °C. Cairkan di kulkas bawah, jangan di suhu ruang.', 'Keep at −18 °C. Thaw in the fridge, never at room temperature.', false, true, true, false, null, 'box', 23),
  ('p_telur', 'telur-ayam', 'c_telur', 'Telur Ayam Negeri', 'Chicken Eggs', null, array['telur','egg','telor']::text[], 'Telur segar dari peternakan Blitar dan Bogor, diantar 2× seminggu ke gudang kami.', 'Fresh eggs from Blitar and Bogor farms, delivered to our store twice a week.', 'Peternakan Blitar & Bogor', 'Blitar and Bogor farms', 'ambient', 'Simpan di tempat sejuk, gunakan dalam 2 minggu.', null, false, true, true, false, '/images/products/telur-ayam.jpg', 'egg', 24),
  ('p_minyak', 'minyak-goreng', 'c_bumbu', 'Minyak Goreng', 'Cooking Oil', null, array['minyak','oil']::text[], 'Minyak goreng sawit kemasan, merek nasional.', 'Packaged palm cooking oil, national brand.', 'Distributor FMCG', 'FMCG distributor', 'ambient', 'Simpan di tempat sejuk dan kering.', 'Store in a cool, dry place.', false, true, true, false, '/images/products/minyak-goreng.jpg', 'bottle', 25),
  ('p_kecap', 'kecap-manis', 'c_bumbu', 'Kecap Manis', 'Sweet Soy Sauce', null, array['kecap','soy sauce']::text[], 'Kecap manis merek nasional, botol atau jerigen untuk dapur restoran.', 'National-brand sweet soy sauce, bottle or jerrycan for restaurant kitchens.', 'Distributor FMCG', 'FMCG distributor', 'ambient', 'Simpan di tempat sejuk dan kering.', 'Store in a cool, dry place.', false, true, true, false, '/images/products/kecap-manis.jpg', 'bottle', 26),
  ('p_sambal', 'sambal-bawang', 'c_bumbu', 'Sambal Bawang', 'Shallot Chili Paste', null, array['sambal','chili']::text[], 'Sambal bawang siap pakai, teman ikan bakar dan ayam goreng.', 'Ready-to-use shallot chilli paste, the partner of grilled fish and fried chicken.', 'Produsen UMKM ber-BPOM', 'BPOM-registered small producer', 'ambient', 'Simpan di kulkas setelah dibuka.', null, false, true, true, false, '/images/products/sambal-bawang.jpg', 'bottle', 27),
  ('p_bawang', 'bawang-putih-kupas', 'c_bumbu', 'Bawang Putih Kupas', 'Peeled Garlic', null, array['garlic','bawang']::text[], 'Bawang putih kupas, hemat 30 menit kerja dapur setiap hari.', 'Peeled garlic: saves 30 minutes of kitchen work every day.', 'Pasar Induk Kramat Jati', 'Kramat Jati wholesale market', 'chilled', 'Simpan 0–4 °C, gunakan dalam 5 hari.', null, false, true, true, false, '/images/products/bawang-putih-kupas.jpg', 'bottle', 28),
  ('p_tepung', 'tepung-bumbu', 'c_bumbu', 'Tepung Bumbu Serbaguna', 'Seasoned Flour', null, array['tepung','flour','tepung crispy']::text[], 'Tepung bumbu untuk ayam dan seafood goreng tepung.', 'Seasoned flour for crispy fried chicken and seafood.', 'Distributor FMCG', 'FMCG distributor', 'ambient', 'Simpan di tempat sejuk dan kering.', 'Store in a cool, dry place.', false, true, true, false, '/images/products/tepung-bumbu.jpg', 'bottle', 29),
  ('p_box_keluarga', 'kotak-freezer-keluarga', 'c_paket', 'Kotak Freezer Keluarga', 'Family Freezer Box', null, array['paket','bundle','freezer box','kotak hemat']::text[], 'Udang kupas PD 500 g, dori fillet 1 kg, nugget ayam 500 g dan sayap ayam 1 kg. Stok protein seminggu untuk keluarga, Rp 9.000 lebih murah dari membeli satuan.', 'Peeled & deveined shrimp 500 g, dori fillet 1 kg, chicken nuggets 500 g and chicken wings 1 kg. A week of family protein, Rp 9,000 below buying separately.', 'Dikemas di meja packing kami', 'Packed at our packing table', 'frozen', 'Simpan −18 °C. Cairkan di kulkas bawah, jangan di suhu ruang.', 'Keep at −18 °C. Thaw in the fridge, never at room temperature.', false, true, true, true, '/images/products/kotak-freezer-keluarga.jpg', 'box', 30),
  ('p_box_seafood', 'kotak-seafood-weekend', 'c_paket', 'Kotak Seafood Weekend', 'Weekend Seafood Box', null, array['paket','bundle','salmon box','kotak seafood']::text[], 'Salmon fillet 2 × 200 g, tuna saku 250 g dan udang kupas PD 500 g. Untuk dua makan malam istimewa dan satu tumisan cepat, Rp 21.000 lebih murah dari satuan.', 'Salmon fillet 2 × 200 g, tuna saku 250 g and peeled & deveined shrimp 500 g. Two special dinners and one quick stir-fry, Rp 21,000 below buying separately.', 'Dikemas di meja packing kami', 'Packed at our packing table', 'frozen', 'Simpan −18 °C. Cairkan di kulkas bawah, jangan di suhu ruang.', 'Keep at −18 °C. Thaw in the fridge, never at room temperature.', false, true, true, true, '/images/products/kotak-seafood-weekend.jpg', 'box', 31)
